{"command": "cd /home/user/rork-app 2>/dev/null

echo "=== USER MESSAGES — WHAT THE OWNER ACTUALLY ASKED FOR ==="
find .rork/history/main/ -name "*_user.json" -type f 2>/dev/null | sort | while read f; do
  python3 -c "
import json
try:
    with open('$f') as fh:
        d = json.load(fh)
        role = d.get('role','')
        if role == 'user':
            contents = d.get('contents', d.get('responseMessageContents', []))
            if isinstance(contents, list):
                for c in contents:
                    text = c.get('text','') if isinstance(c, dict) else str(c)
                    if text and len(text) > 10:
                        # Skip system prompts
                        if not text.startswith('{') and not text.startswith('You are'):
                            print(f'--- {d.get(\"id\",\"?\")[:12]} ---')
                            print(text[:300])
                            print()
except:
    pass
" 2>/dev/null
done | head -300"}

